from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/emotion', methods=['POST'])
def emotion():
    data = request.get_json()
    emotion = data['emotion']
    effort = data['effort']
    response = {
        "Question 1": f"I would feel {emotion}.",
        "Question 2": [f"I felt like I needed to {effort} to process this situation.", int(effort)]
    }
    return jsonify(response)

if __name__ == '__main__':
    app.run(debug=True)
```

